-- Quantora: civil measurement rule library, starter set (24 Oct 2026)
-- BASE = the platform's own house rules. POMI / NRM2 / IS1200 start as copies of
-- BASE marked UNVERIFIED: a QS checks each against the standard and marks it
-- verified (verification_status, verified_by, verified_at). Until then every line
-- measured with them is 'Calculated - Review Required', never 'Verified'.
-- Re-running replaces version 1 of these codes only.
delete from public.civil_measurement_rules where version = 1 and standard in ('BASE','POMI','NRM2','IS1200')
  and verification_status = 'unverified';
