-- POMI / NRM2 / IS1200 start as unverified copies of BASE.
insert into public.civil_measurement_rules
  (standard, edition, rule_code, work_category, item_type, unit, measurement_basis, formula_hint, deduct_openings,
   deduction_threshold, deduction_unit, inclusions, rounding_dp, verification_status, source_note, test_cases)
select s.std, null, s.std || substr(b.rule_code, 5), b.work_category, b.item_type, b.unit, b.measurement_basis, b.formula_hint,
       b.deduct_openings, b.deduction_threshold, b.deduction_unit, b.inclusions, b.rounding_dp, 'unverified',
       'Parameters copied from the Quantora base rules. NOT yet checked against the ' || s.label ||
       ' text; a quantity surveyor must confirm the unit, deductions and thresholds before this rule is marked verified.',
       b.test_cases
  from public.civil_measurement_rules b
  cross join (values ('POMI', 'POMI'), ('NRM2', 'RICS NRM2'), ('IS1200', 'IS 1200')) as s(std, label)
 where b.standard = 'BASE' and b.version = 1
on conflict (standard, rule_code, version) do nothing;
